const patch = "*** Begin Patch
*** Add File: /tmp/travel-app-seat-hold-prototype.mjs
+import assert from 'node:assert/strict';
+
+class HoldTable {
+    rows = new Map();
+
+    hold(flightId, seatNumber, holderKey) {
+        const key = `${flightId}:${seatNumber}`;
+        const owner = this.rows.get(key);
+        if (owner && owner !== holderKey) return false;
+        this.rows.set(key, holderKey);
+        return true;
+    }
+
+    releaseExcept(flightIds, holderKey, keep) {
+        const kept = new Set(keep.map(({ flightId, seatNumber }) => `${flightId}:${seatNumber}`));
+        for (const [seat, owner] of this.rows) {
+            const flightId = Number(seat.slice(0, seat.indexOf(':')));
+            if (flightIds.includes(flightId) && owner === holderKey && !kept.has(seat)) {
+                this.rows.delete(seat);
+            }
+        }
+    }
+
+    consume(holderKey, seats) {
+        for (const { flightId, seatNumber } of seats) {
+            assert.equal(this.rows.get(`${flightId}:${seatNumber}`), holderKey);
+        }
+        for (const { flightId, seatNumber } of seats) {
+            this.rows.delete(`${flightId}:${seatNumber}`);
+        }
+    }
+}
+
+function holderKey(userId, checkoutId) {
+    return `${userId}:${checkoutId}`;
+}
+
+const flightId = 42;
+
+// Current behavior: two tabs share the user's holder key. Tab B's cleanup
+// removes Tab A's seat because the database cannot tell the checkouts apart.
+{
+    const holds = new HoldTable();
+    const shared = 'user-1';
+    assert.equal(holds.hold(flightId, '12A', shared), true);
+    holds.releaseExcept([flightId], shared, [{ flightId, seatNumber: '12B' }]);
+    assert.equal(holds.rows.has(`${flightId}:12A`), false);
+}
+
+// Proposed behavior: the authenticated user remains part of server-derived
+// ownership, while each mounted checkout gets an independent identifier.
+{
+    const holds = new HoldTable();
+    const tabA = holderKey('user-1', 'checkout-a');
+    const tabB = holderKey('user-1', 'checkout-b');
+
+    assert.equal(holds.hold(flightId, '12A', tabA), true);
+    holds.releaseExcept([flightId], tabB, [{ flightId, seatNumber: '12B' }]);
+    assert.equal(holds.hold(flightId, '12B', tabB), true);
+    assert.equal(holds.rows.get(`${flightId}:12A`), tabA);
+    assert.equal(holds.rows.get(`${flightId}:12B`), tabB);
+
+    // Checkout isolation does not weaken collision protection.
+    assert.equal(holds.hold(flightId, '12A', tabB), false);
+
+    // The later atomic-conversion slice can consume only the booking checkout's
+    // rows and leave another checkout by the same user untouched.
+    holds.consume(tabA, [{ flightId, seatNumber: '12A' }]);
+    assert.equal(holds.rows.has(`${flightId}:12A`), false);
+    assert.equal(holds.rows.get(`${flightId}:12B`), tabB);
+}
+
+console.log('prototype passed: checkout keys isolate tabs and preserve collisions');
*** End Patch";
